import * as THREE from 'three';
import { markSharedGeometry } from './materials.js';

// Runtime side of the CC0 photo-texture / HDRI library in public/media/.
//
// WHAT IS ON DISK (built offline from Poly Haven + ambientCG CC0 sources; see
// public/media/CREDITS.md and design/research-assets.md sections 4-10)
//   media/tex/1024/<set>_<kind>.webp   top tier  (terrain + airfield sets)
//   media/tex/512/<set>_<kind>.webp    medium tier (every set; buildings and
//                                      vehicle sets exist ONLY at 512)
//   media/hdri/512/<id>.rgbe.webp      HDRIs, 512x256 RGBE in lossless WebP
//
// KINDS AND CHANNEL PACKING (files are opaque RGB unless stated)
//   c    albedo DETAIL, sRGB. Mean-neutralised: every channel has a LINEAR mean
//        of 0.5, so the calibrated game colour still decides the tint:
//          albedoLinear = texture(c).rgb * 2.0 * calibratedLinearColour
//        (terrain c also has the photo AO folded in at strength 0.5).
//   n    terrain:   RGBA = (normal X, normal Y, roughness, height) once loaded;
//                   Z = sqrt(1 - x*x - y*y); height 0..1, mean ~0.5, high-passed
//                   (for height-blending layers). On disk it is a 2N x 2N
//                   greyscale WebP of four quadrants (X | Y over rough | height),
//                   because RGB WebP's 4:2:0 chroma wrecks packed normals (13 deg
//                   mean error measured, vs ~3 deg this way); this module unpacks.
//        surface/prop: RGB = tangent normal XYZ (stock three normalMap).
//        detail (vehicles, RGBA): R,G = normal X,Y; B = roughness variation
//                   (mean 0.5: rough *= 2.0*B); A = luminance variation
//                   (mean 0.5: albedo *= mix(1.0, 2.0*A, k)).
//        Normal convention for EVERY n map: OpenGL tangent space with +G = +v
//        for textures uploaded with flipY = false (this module never flips) -
//        i.e. exactly the convention of world/terrain.js normalTex(). The build
//        pre-negated Poly Haven/ambientCG "GL" green to get there and checked the
//        sign against each set's height map.
//   arm  surface sets: R = AO, G = roughness, B = metalness (three's aoMap /
//        roughnessMap / metalnessMap read .r/.g/.b, so one texture feeds all three).
//   w    vehicle_wear: R = chip distance field (chip = step(chipThreshold[pct], R)),
//        G = dust/grime film, B = fine scratches.
//
// RUNTIME CONTRACT
//   * Every loader returns IMMEDIATELY with a neutral placeholder (4x4, or 4x4xN
//     for arrays, or 8x4 for HDRIs) that already has the final sampler type,
//     colour space and wrap/filter state, so a material can bind it and compile
//     once. When the file has decoded the SAME texture object is filled in place
//     (dispose + new image + needsUpdate), so uniforms never have to be re-set.
//   * Everything is cached and stamped shared (core/materials.js
//     isSharedResource() is true). A battle teardown must skip these; free them
//     only through releaseAsset() / releaseTerrainExcept() / disposeAssets().
//   * Headless (node, no createImageBitmap) or setAssetsEnabled(false): nothing is
//     fetched, placeholders stay, the ready promises resolve at once. Never throws.
//   * Loads are SCHEDULED by priority (LOAD_PRIORITY; opts.priority overrides):
//     building / airfield scans first, then vehicle detail and HDRIs, then the
//     terrain arrays, speculative prefetch last. Work for a released texture is
//     dropped. Decoding runs in a worker where the browser allows it, so it goes
//     on while the main thread is busy (shader compiles); see "fetch + decode
//     scheduling". When the queue has been idle a while (the hangar), the
//     compressed files of every style / biome are prefetched into memory
//     (prefetchAssets), so a cold first battle decodes without the network.

// ---------------------------------------------------------------------------
// manifest (generated by the asset build; do not edit by hand)
// sets[id]: consumer, role, label, ref, tile (metres per texture repeat), biomes|styles,
//   src, page, authors, licence, mean (raw photo linear RGB mean), meanHex, meanY,
//   rough, kinds, neutral{kind: [r,g,b,a] bytes}, packing, files{tier: {kind: [path, bytes]}}
// terrain[biome]: slot -> set id; airfield, buildings[style], vehicles: role -> set id
// hdri[id]: sunElevDeg, sunYawDeg (game yaw: dir = (sin yaw, y, cos yaw)), sunShareRaw,
//   eskyRaw, groundToSky, scale, files{512: [path, bytes, w, h]}
// hdriFor[biome][dawn|noon|haze|dusk|overcast] -> hdri id
